// Unlock the work object's pxLockHandle
String strLockHandle = myStepPage.getString(".pxLockHandle");
if (strLockHandle.length() > 0)
{
   boolean success = false;
   try { 
      // note that we don't affect locks in different requestors when
      // we close a work object.
      success = tools.getDatabase().getLockManager().unlock(strLockHandle, false);
   } catch (DatabaseException e) {
      oLog.error(e.getMessage());	
      myStepPage.addMessage(e.getMessage());										
   }

   if (!success)
   {
      myStepPage.addMessage("Unable to unlock " + strLockHandle);
   }
}

// These are the page names generated when a flow spawned 'on different object' completes
pega_rules_page.removePagesThatStartWith("pyPrevObj");

// These are the page names generated when spawning a flow 'on different object'
pega_rules_page.removePagesThatStartWith("pyNextObj");

// These are the parent cover page names generated when resolving a cover chain
pega_rules_page.removePagesThatStartWith("pyWorkCover_");

java.util.Set threadNames = tools.getThread().getRequestor().getThreadNames();
String currentThreadContext = tools.getThread().getName();
String threadName ="";
Iterator threadIter = threadNames.iterator();
            ParameterPage p = new ParameterPage();
            p.putString("removeFromClipboard","true");
            p.putString("workOnly","true");
while(threadIter.hasNext()){

	threadName = (String)threadIter.next();

	if(threadName.indexOf("/$WorkProcessing") != -1 && !threadName.equals(currentThreadContext) && threadName.startsWith(currentThreadContext)){
	    PRThread baseThread = tools.getRequestor().getThread(threadName);
	    baseThread.clearActivityLists();
		ClipboardPage workPage = baseThread.getPage("pyWorkPage");
		if(workPage != null && !workPage.getClassName().equals("")){
			baseThread.appendActivity(baseThread.LIST_ACTIVITY,"Work-","WorkUnlock",baseThread.getPage("pyWorkPage"),p);
			baseThread.runActivities();
		}
		/*try {
		   ((com.pega.pegarules.priv.context.PegaRequestor)tools.getThread().getRequestor()).removeInactiveThread(threadName);

		}
		catch (java.lang.IllegalArgumentException e) { 
		}*/
	}
}
